**add.go**

```go
package calc

func normalise(value int) int {
	if value < 0 {
		return 0
	}
	return value
}

func Add(a, b int) int { return normalise(a) + normalise(b) }
```

**add_internal_test.go**

```go
package calc

import "testing"

func TestNormalise(t *testing.T) {
	if normalise(-2) != 0 {
		t.Fatal("negative input was not normalised")
	}
}
```

**add_external_test.go**

```go
package calc_test

import (
	"testing"

	calc "example.test/calc"
)

func TestAdd(t *testing.T) {
	if got := calc.Add(-2, 5); got != 5 {
		t.Fatalf("Add = %d; want 5", got)
	}
}
```

**Run it**

```bash
go test ./...
go list -f '{{.Name}}'
```

The production directory remains package `calc`; the special external test package models an importing user.
